#[test]
fn output_modes_match_frozen_go_oracle() {
    let fixture = load_fixture();
    assert_eq!(fixture.schema_version, 1, "fixture schema version");
    assert_eq!(fixture.cases.len(), EXPECTED_CASES, "fixture case count");
    if fixture.oracle.goos != recording_goos() {
        eprintln!(
            "SKIP output-mode corpus recorded on {}, running on {}; the gate runs it on the recording platform",
            fixture.oracle.goos,
            recording_goos()
        );
        return;
    }
    let mut ids: Vec<&str> = fixture.cases.iter().map(|case| case.id.as_str()).collect();
    ids.sort_unstable();
    ids.dedup();
    assert_eq!(ids.len(), EXPECTED_CASES, "case ids are unique");
    assert_eq!(fixture.seeds.len(), EXPECTED_SEEDS, "seed count");
    let seeds: BTreeMap<&str, &Seed> = fixture
        .seeds
        .iter()
        .map(|seed| (seed.name.as_str(), seed))
        .collect();
    let binary = PathBuf::from(
        std::env::var_os("SYMVAULT_OUTPUT_MODES_BINARY")
            .unwrap_or_else(|| env!("CARGO_BIN_EXE_symvault").into()),
    );

    let next = AtomicUsize::new(0);
    let executed = AtomicUsize::new(0);
    let failures: Mutex<Vec<(String, String, String)>> = Mutex::new(Vec::new());
    let threads = std::thread::available_parallelism()
        .map_or(2, usize::from)
        .min(8);
    std::thread::scope(|scope| {
        for _ in 0..threads {
            scope.spawn(|| {
                loop {
                    let index = next.fetch_add(1, Ordering::Relaxed);
                    let Some(case) = fixture.cases.get(index) else {
                        break;
                    };
                    executed.fetch_add(1, Ordering::Relaxed);
                    let problems = run_case(&binary, &seeds, case);
                    if !problems.is_empty() {
                        failures.lock().expect("failure list").push((
                            case.id.clone(),
                            case.path.clone(),
                            format!(
                                "case {} ({:?}):\n  - {}",
                                case.id,
                                case.argv,
                                problems.join("\n  - ")
                            ),
                        ));
                    }
                }
            });
        }
    });
    let executed = executed.load(Ordering::Relaxed);
    assert_eq!(executed, EXPECTED_CASES, "every case is executed");
    let mut failures = failures.into_inner().expect("failure list");
    failures.sort();
    let mut per_path: BTreeMap<&str, usize> = BTreeMap::new();
    for (_, path, _) in &failures {
        *per_path.entry(path.as_str()).or_default() += 1;
    }
    assert!(
        failures.is_empty(),
        "{} of {} output-mode cases differ from the Go oracle (per path: {:?}):\n{}",
        failures.len(),
        executed,
        per_path,
        failures
            .iter()
            .map(|(_, _, text)| text.as_str())
            .collect::<Vec<_>>()
            .join("\n")
    );
}

/// Every accepting gate path is covered, in every mode the gate accepts, by at
/// least one executed case; residuals name a partial case that exists.
#[test]
fn matrix_covers_every_accepting_gate_path_and_mode() {
    let fixture = load_fixture();
    let gate = load_gate();
    let accepting = accepting_rows(&gate);
    assert_eq!(accepting.len(), EXPECTED_PATHS, "accepting gate paths");
    let mut per_path: BTreeMap<&str, BTreeSet<&str>> = BTreeMap::new();
    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
    for case in &fixture.cases {
        let row = accepting
            .iter()
            .find(|row| gate_path(row) == case.path)
            .unwrap_or_else(|| panic!("case {} names a non-accepting path {}", case.id, case.path));
        assert!(
            mode_accepted(row, &case.mode),
            "case {} runs a mode the gate refuses",
            case.id
        );
        assert_eq!(case.id, format!("{}.{}", case.scenario, case.mode));
        let expected_flags = mode_args(&case.mode);
        assert!(
            case.argv.ends_with(&expected_flags),
            "case {} argv does not end with its mode flags",
            case.id
        );
        per_path
            .entry(case.path.as_str())
            .or_default()
            .insert(case.mode.as_str());
        *counts.entry(case.path.as_str()).or_default() += 1;
    }
    for row in &accepting {
        let path = gate_path(row);
        let modes = per_path
            .get(path)
            .unwrap_or_else(|| panic!("accepting path {path:?} has no case"));
        for mode in ["text", "json", "yaml", "output-json", "quiet"] {
            if mode_accepted(row, mode) {
                assert!(
                    modes.contains(mode),
                    "path {path:?}: accepted mode {mode} has no case"
                );
            }
        }
        assert!(counts[path] > 0, "path {path:?}: zero cases");
    }
    assert_eq!(per_path.len(), EXPECTED_PATHS);
    for residual in &fixture.residuals {
        assert!(
            per_path.contains_key(residual.path.as_str()),
            "residual {:?} has no pinned partial case",
            residual.path
        );
        assert!(!residual.reason.is_empty() && !residual.partial.is_empty());
    }
}

fn digest_of(root: &Path, names: &[String]) -> String {
    // provenance.Digest format: sha256 over name/NUL/content/NUL in order.
    let mut hasher = Sha256::new();
    for name in names {
        let content = std::fs::read(root.join(format!("{name}.txt")))
            .unwrap_or_else(|error| panic!("read {name}: {error}"));
        hasher.update(name.as_bytes());
        hasher.update([0u8]);
        hasher.update(&content);
        hasher.update([0u8]);
    }
    hex::encode(hasher.finalize())
}

#[test]
fn fixture_provenance_matches_checkout() {
    let fixture = load_fixture();
    let oracle = &fixture.oracle;
    assert_eq!(oracle.commit.len(), 40, "oracle commit is a full sha");
    assert_eq!(
        oracle.commit, oracle.commit_sha,
        "pinned commit resolves to itself"
    );
    for files in [&oracle.source_files, &oracle.generator_files] {
        let mut sorted = files.clone();
        sorted.sort();
        assert_eq!(&sorted, files, "file lists are stored sorted");
    }
    let root = manifest_path("../../testdata/port/go-snapshots");
    assert_eq!(
        digest_of(&root, &oracle.source_files),
        oracle.source_digest,
        "Go contract source changed since fixture capture — re-freeze \
         testdata/port/cli/output-modes.json (make output-modes-regenerate)"
    );
    assert_eq!(
        digest_of(&root, &oracle.generator_files),
        oracle.generator_digest,
        "generator changed since fixture capture — re-freeze the fixture \
         (make output-modes-regenerate)"
    );
    // The gate rows that decide which modes run are part of the provenance:
    // json.Marshal([]gateRow) in the generator, spelled out here.
    let canonical = format!(
        "[{}]",
        load_gate()
            .iter()
            .map(|row| format!(
                "{{\"path\":{},\"json_refused\":{},\"output_refused\":{}}}",
                serde_json::to_string(&row.path).expect("path"),
                row.json_refused,
                row.output_refused
            ))
            .collect::<Vec<_>>()
            .join(",")
    );
    assert_eq!(
        sha_hex(canonical.as_bytes()),
        oracle.gate_digest,
        "error-taxonomy.json gate changed since fixture capture — re-freeze the fixture"
    );
}

#[test]
fn volatile_rules_are_narrow() {
    let text = |bytes: Vec<u8>| String::from_utf8(bytes).expect("utf8");
    // Rule 3.
    assert_eq!(
        text(normalize_dated_ids(b"id=tok-20261031-0a1b2c3d.")),
        "id=tok-<DATE>-<RAND>."
    );
    for kept in [
        "tok-20261031-0A1B2C3D",
        "tok-20261331-0a1b2c3d",
        "tok-20261031-0a1b2c3",
        "other-20261031-0a1b2c3d",
    ] {
        assert_eq!(text(normalize_dated_ids(kept.as_bytes())), kept, "{kept}");
    }
    // Rule 6.
    assert_eq!(
        text(normalize_temp_suffixes(b"a.age.tmp-123 b.age.tmp-x")),
        "a.age.tmp-<N> b.age.tmp-x"
    );
    // Rule 9: only the date field of a `.TH` header.
    assert_eq!(
        text(replace_man_date(
            b".TH \"SYMVAULT\" \"1\" \"Nov 2026\" \"Symaira Vault\"\n.SH Nov 2026\n"
        )),
        ".TH \"SYMVAULT\" \"1\" \"<MAN-DATE>\" \"Symaira Vault\"\n.SH Nov 2026\n"
    );
    for kept in [
        ".TH \"SYMVAULT\" \"1\" \"November 2026\" \"x\"\n",
        ".TH \"SYMVAULT\" \"1\" \"nov 2026\" \"x\"\n",
        "x .TH \"SYMVAULT\" \"1\" \"Nov 2026\" \"x\"\n",
        "2-November-2026 Auto generated by spf13/cobra\n",
        "x 2-Nov-2026 Auto generated by spf13/cobra\n",
        "123-Nov-2026 Auto generated by spf13/cobra\n",
    ] {
        assert_eq!(text(replace_man_date(kept.as_bytes())), kept, "{kept}");
    }
    // Rule 9: cobra's HISTORY date, one or two day digits.
    for day in ["2", "12"] {
        assert_eq!(
            text(replace_man_date(
                format!("{day}-Nov-2026 Auto generated by spf13/cobra\n").as_bytes()
            )),
            "<MAN-DATE> Auto generated by spf13/cobra\n"
        );
    }
    // Rule 4: exactly one delimited run of the declared length.
    assert_eq!(
        text(replace_generated_password(b"{\"password\":\"aB3dE5gH7jK9mN1pQ3rS\"}\n", 20).unwrap()),
        "{\"password\":\"<PW>\"}\n"
    );
    assert!(replace_generated_password(b"short\n", 20).is_err());
    assert!(
        replace_generated_password(b"aB3dE5gH7jK9mN1pQ3rS aB3dE5gH7jK9mN1pQ3rS\n", 20).is_err()
    );
    assert!(replace_generated_password(b"aB3dE5gH7jK9mN1pQ3rSt\n", 20).is_err());
    // Rule 5.
    assert_eq!(
        find_pair_token(b"x\nToken: 6SJJ1P42PH2291TQJNRG4TTTFLOR2A90\n").unwrap(),
        "6SJJ1P42PH2291TQJNRG4TTTFLOR2A90"
    );
    assert!(find_pair_token(b"Token: lowercaselowercaselowercase12345\n").is_err());
    assert!(find_pair_token(b"nothing\n").is_err());
    // Rule 7: only stamps near the run are rewritten.
    let now = OffsetDateTime::parse("2026-10-31T22:00:00Z", &Rfc3339).unwrap();
    assert_eq!(
        text(replace_now_timestamps(
            b"a 2026-10-31T22:03:23.8608843Z b 2025-02-03T04:05:06Z c 2026-10-31T23:30:00+00:00",
            now
        )),
        "a <NOW> b 2025-02-03T04:05:06Z c 2026-10-31T23:30:00+00:00"
    );
    assert_eq!(
        scan_timestamp(b"2026-10-31T22:00:00"),
        0,
        "no zone is no stamp"
    );
}

