/// The numbered rules are listed once and consistently: the header of this file,
/// the header of the generator, the notes the generator wrote into the fixture
/// and `RULES` (what the replay implements) carry the same ids in the same order.
#[test]
fn normalization_rules_are_listed_once_and_consistently() {
    fn header_rule_ids(source: &str, comment: &str) -> Vec<String> {
        source
            .lines()
            .take(100)
            .filter_map(|line| {
                let rest = line.strip_prefix(comment)?.trim_start();
                let (number, rest) = rest.split_once(". `")?;
                number.parse::<usize>().ok()?;
                Some(rest.split_once('`')?.0.to_owned())
            })
            .collect()
    }
    let rules: Vec<String> = RULES.iter().map(|id| (*id).to_owned()).collect();
    assert_eq!(
        header_rule_ids(include_str!("output_modes.rs"), "//!"),
        rules,
        "tests/output_modes.rs header"
    );
    let generator = std::fs::read_to_string(manifest_path(
        "../../testdata/port/go-snapshots/scripts/rust-port/cmd/outputmodegen/main.go.txt",
    ))
    .expect("read generator");
    assert_eq!(
        header_rule_ids(&generator, "//"),
        rules,
        "outputmodegen main.go header"
    );
    let notes: Vec<String> = load_fixture()
        .notes
        .iter()
        .filter_map(|note| note.strip_prefix("Normalization rule "))
        .enumerate()
        .map(|(index, rest)| {
            let (number, rest) = rest.split_once(" (").expect("rule note shape");
            assert_eq!(
                number,
                (index + 1).to_string(),
                "rule numbers are contiguous"
            );
            rest.split_once("):").expect("rule note id").0.to_owned()
        })
        .collect();
    assert_eq!(notes, rules, "fixture notes");
    for case in &load_fixture().cases {
        for rule in &case.rules {
            let id = rule.split(':').next().unwrap_or(rule);
            assert!(
                RULES.contains(&id),
                "case {} declares unknown rule {rule}",
                case.id
            );
        }
    }
}

/// The Touch ID probe is normalized to `<BOOL>` (rule 5), so it is checked live:
/// on darwin, with the pinned Go oracle at `SYMVAULT_OUTPUT_MODES_GO_BINARY`
/// (set by `check_output_modes_cli.sh`), `auth status --json` of Rust and Go in
/// the same sandbox reports the same `touchIDAvailable`.
#[test]
fn touch_id_availability_matches_go_in_the_same_sandbox() {
    if recording_goos() != "darwin" {
        eprintln!(
            "SKIP touch-id live comparison: darwin only (running on {})",
            recording_goos()
        );
        return;
    }
    let Some(go) = std::env::var_os("SYMVAULT_OUTPUT_MODES_GO_BINARY")
        .map(PathBuf::from)
        .filter(|path| path.is_file())
    else {
        eprintln!(
            "SKIP touch-id live comparison: no Go oracle (SYMVAULT_OUTPUT_MODES_GO_BINARY unset or missing; make output-modes-cli-differential sets it)"
        );
        return;
    };
    let fixture = load_fixture();
    let seed = fixture
        .seeds
        .iter()
        .find(|seed| seed.name == "entries")
        .expect("entries seed");
    let rust = PathBuf::from(
        std::env::var_os("SYMVAULT_OUTPUT_MODES_BINARY")
            .unwrap_or_else(|| env!("CARGO_BIN_EXE_symvault").into()),
    );
    let sandbox = Sandbox::new(&rust);
    sandbox.materialize_seed(&seed.files);
    let args = ["auth".to_owned(), "status".to_owned(), "--json".to_owned()];
    let probe = |binary: &Path| -> bool {
        let output = sandbox.run_raw(binary, &args, &BTreeMap::new(), "");
        let value: serde_json::Value = serde_json::from_slice(&output.stdout)
            .unwrap_or_else(|error| panic!("auth status --json is JSON: {error}"));
        value["touchIDAvailable"]
            .as_bool()
            .unwrap_or_else(|| panic!("touchIDAvailable in {value}"))
    };
    assert_eq!(
        probe(&rust),
        probe(&go),
        "Touch ID availability differs between Rust and the Go oracle on this host"
    );
}

/// Negative control for the audit comparison: a presence-only audit log is
/// compared by its decoded stable fields, so a different agent, action, path,
/// field, outcome, hash shape or signature is a difference, while the clock and
/// the HMAC bytes are not.
#[test]
fn audit_logs_are_compared_by_decoded_fields_not_presence() {
    let line = |agent: &str, extra: &str| {
        format!(
            "{{\"ts\":\"2026-11-01T00:00:00Z\",\"agent\":\"{agent}\",\"action\":\"expose_plaintext\",\"path\":\"work/example\",{extra}\"kid\":\"fc75e246\",\"hmac\":\"00\",\"argv_hash\":\"37bd64d6d7b42557\",\"ok\":true}}\n"
        )
    };
    let go = decode_audit_lines(line("", "").as_bytes());
    assert_eq!(
        go,
        vec![AuditLine {
            agent: String::new(),
            action: "expose_plaintext".into(),
            path: "work/example".into(),
            field: String::new(),
            ok: true,
            argv_hash_len: 16,
            signed: true,
        }]
    );
    let other_clock = line("", "").replace("2026-11-01T00:00:00Z", "2030-01-01T00:00:00Z");
    assert_eq!(
        decode_audit_lines(other_clock.as_bytes()),
        go,
        "ts is not compared"
    );
    assert_ne!(
        decode_audit_lines(line("symvault", "").as_bytes()),
        go,
        "agent is compared"
    );
    assert_ne!(
        decode_audit_lines(line("", "\"field\":\"password\",").as_bytes()),
        go,
        "field is compared"
    );
    assert_ne!(
        decode_audit_lines(
            line("", "")
                .replace("\"ok\":true", "\"ok\":false")
                .as_bytes()
        ),
        go,
        "outcome is compared"
    );
    assert_ne!(
        decode_audit_lines(line("", "").replace("37bd64d6d7b42557", "37bd").as_bytes()),
        go,
        "argv_hash length is compared"
    );
    assert_ne!(
        decode_audit_lines(
            line("", "")
                .replace("\"hmac\":\"00\"", "\"hmac\":\"\"")
                .as_bytes()
        ),
        go,
        "an unsigned line differs"
    );
}

/// Declared D1 difference (DIST-005): Rust takes a verified backup before the
/// first mutation of an unmarked vault, so a Rust run leaves the `.symvault-rust`
/// marker in the vault and the archive below `$HOME/.local/state/symvault`.
/// Go does neither; the data-safety contract
/// (`make data-safety-differential`) verifies them, so the Go-parity tree
/// comparisons look past exactly these paths.
fn d1_artifact(path: &std::path::Path) -> bool {
    if path
        .file_name()
        .is_some_and(|name| name == ".symvault-rust")
    {
        return true;
    }
    let text = path.to_string_lossy();
    // `.git/info/exclude` keeps the marker out of `git add --all`; Go-created
    // repositories have no `.git/info`.
    if text.ends_with("/.git/info/exclude") || text.ends_with("/.git/info") {
        return true;
    }
    if text.ends_with(".local/state/symvault") || text.contains(".local/state/symvault/") {
        return true;
    }
    // `.local` and `.local/state` exist only because the backup created them.
    let only = |dir: &std::path::Path, child: &str| {
        std::fs::read_dir(dir).is_ok_and(|entries| {
            let names: Vec<_> = entries.flatten().map(|e| e.file_name()).collect();
            names.len() == 1 && names[0] == child
        })
    };
    (text.ends_with("/.local") && only(path, "state") && only(&path.join("state"), "symvault"))
        || (text.ends_with("/.local/state") && only(path, "symvault"))
}

// --- declared divergences: coverage and negative controls --------------------------

/// The cases that carry a `declared_divergence` (ADR 0034 items 3, 5, 8, 10).
const DECLARED_CASES: usize = 13;

fn go_live(case: &Case) -> Live {
    Live {
        exit: case.exit,
        stdout: case.stdout.clone().into_bytes(),
        stderr: case.stderr.clone().into_bytes(),
        tree: case.tree.clone(),
        files: case
            .files_after
            .iter()
            .map(|file| (file.path.clone(), file.exists.then(|| file.text.clone())))
            .collect(),
        post: case
            .post
            .iter()
            .map(|step| (step.exit, step.stdout.clone().into_bytes()))
            .collect(),
    }
}

/// Every labelled case has a declaration and every declaration a labelled case;
/// the labels name only the four ADR 0034 items that need a pin.
#[test]
fn declared_divergences_cover_every_labelled_case() {
    let fixture = load_fixture();
    let labelled: BTreeSet<&str> = fixture
        .cases
        .iter()
        .filter(|case| !case.declared_divergence.is_empty())
        .map(|case| case.id.as_str())
        .collect();
    let declared: BTreeSet<&str> = DECLARED.iter().map(|d| d.id).collect();
    assert_eq!(labelled, declared, "labelled cases and DECLARED agree");
    assert_eq!(declared.len(), DECLARED.len(), "one declaration per case");
    assert_eq!(declared.len(), DECLARED_CASES);
    let items: BTreeSet<&str> = DECLARED.iter().map(|d| d.item).collect();
    assert_eq!(
        items,
        BTreeSet::from([ITEM3, ITEM5, ITEM8, ITEM10]),
        "items pinned here"
    );
    for case in &fixture.cases {
        if case.declared_divergence.is_empty() {
            assert!(
                case.files_after.is_empty(),
                "{}: files_after belongs to declared cases",
                case.id
            );
        }
    }
}

/// Negative control per pin: the declaration accepts exactly the declared run
/// and rejects Go's behaviour (the divergence closed) and a one-field mutation of
/// every observed value (exit, stdout, stderr, each file, the tree, each post).
#[test]
fn declared_divergences_reject_go_behaviour_and_mutations() {
    let fixture = load_fixture();
    for declared in DECLARED {
        let case = fixture
            .cases
            .iter()
            .find(|case| case.id == declared.id)
            .unwrap_or_else(|| panic!("{}: not in the fixture", declared.id));
        let good = declared_expectation(case, declared).unwrap_or_else(|e| panic!("{e}"));
        assert_eq!(
            declared_problems(case, declared, &good),
            Vec::<String>::new(),
            "{}: the declared run is accepted",
            declared.id
        );
        let rejected = declared_problems(case, declared, &go_live(case));
        assert!(
            !rejected.is_empty(),
            "{}: Go's own behaviour must be rejected as the closed divergence",
            declared.id
        );

        let mut mutations: Vec<(&str, Live)> = Vec::new();
        let rebuild = || declared_expectation(case, declared).expect("expectation");
        let mut m = rebuild();
        m.exit += 1;
        mutations.push(("exit", m));
        let mut m = rebuild();
        m.stdout.extend_from_slice(b"x");
        mutations.push(("stdout", m));
        let mut m = rebuild();
        m.stderr.extend_from_slice(b"x");
        mutations.push(("stderr", m));
        let mut m = rebuild();
        m.tree.push(TreeEntry {
            path: "home/extra".to_owned(),
            change: "added".to_owned(),
            kind: "file".to_owned(),
            sha256: String::new(),
            mode: 0o600,
            members: Vec::new(),
            audit: Vec::new(),
        });
        mutations.push(("tree", m));
        for path in good.files.keys() {
            let mut m = rebuild();
            let slot = m.files.get_mut(path).expect("file slot");
            *slot = Some(slot.take().unwrap_or_default() + "x");
            mutations.push(("file", m));
        }
        for index in 0..good.post.len() {
            let mut m = rebuild();
            m.post[index].1.extend_from_slice(b"x");
            mutations.push(("post", m));
        }
        for (what, live) in mutations {
            assert!(
                !declared_problems(case, declared, &live).is_empty(),
                "{}: a mutated {what} must be detected",
                declared.id
            );
        }
        // The tree of a declared file carries the digest of the declared text.
        for decl in declared.files {
            let want = good.files[decl.path].clone().expect("declared file text");
            let entry = good
                .tree
                .iter()
                .find(|entry| entry.path == decl.path)
                .expect("declared file in the tree");
            assert_eq!(entry.sha256, sha_hex(want.as_bytes()), "{}", declared.id);
        }
    }
}

/// A declaration that does not differ from Go, or whose edit no longer matches
/// Go's recording, is refused: the pin can neither outlive its cause nor drift.
#[test]
fn declared_divergence_must_differ_from_go_and_match_the_recording() {
    let fixture = load_fixture();
    let case = fixture
        .cases
        .iter()
        .find(|case| case.id == "config-set-recoerce-y.text")
        .expect("item 3 case");
    let same = Declared {
        id: "config-set-recoerce-y.text",
        item: ITEM3,
        exit: Some(case.exit),
        stdout: Text::Full(Box::leak(case.stdout.clone().into_boxed_str())),
        stderr: Text::Same,
        files: &[],
        post: &[],
    };
    let live = go_live(case);
    let problems = declared_problems(case, &same, &live);
    assert!(
        problems
            .iter()
            .any(|p| p.contains("equals Go's") || p.contains("no declared difference")),
        "{problems:?}"
    );
    let stale = Declared {
        id: "config-set-recoerce-y.text",
        item: ITEM3,
        exit: None,
        stdout: Text::Same,
        stderr: Text::Same,
        files: &[DeclaredFile {
            path: CONFIG,
            change: "changed",
            mode: 0o600,
            text: Text::Edits(&[Edit {
                from: "vaultDir: \"never recorded\"\n",
                to: "vaultDir: y\n",
                count: 1,
            }]),
        }],
        post: &[],
    };
    let problems = declared_problems(case, &stale, &live);
    assert!(
        problems.iter().any(|p| p.contains("found 0 times")),
        "{problems:?}"
    );
}
